};

import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { Play, Pause, Music } from 'lucide-react';

interface TocaPlayerProps {
  trackName: string;
  isDark?: boolean;
}

export const TocaPlayer: React.FC<TocaPlayerProps> = ({ trackName, isDark = false }) => {
  const [isPlaying, setIsPlaying] = useState(false);

  return (
    <motion.button
      initial={{ y: -50, opacity: 0 }}
      animate={{ y: 0, opacity: 1 }}
      transition={{ delay: 1 }}
      onClick={() => setIsPlaying(!isPlaying)}
      className={`
        fixed top-4 right-4 z-40 flex items-center gap-2 pl-3 pr-4 py-2 rounded-full 
        backdrop-blur-md border shadow-lg cursor-pointer
        ${isDark 
          ? 'bg-black/40 border-white/10 text-white hover:bg-black/60' 
          : 'bg-white/40 border-white/40 text-slate-800 hover:bg-white/60'}
      `}
    >
      <div className={`p-1.5 rounded-full ${isDark ? 'bg-white text-black' : 'bg-black text-white'}`}>
        {isPlaying ? <Pause size={10} fill="currentColor" /> : <Play size={10} fill="currentColor" />}
      </div>

      <div className="flex flex-col items-start leading-none">
        <span className="text-[10px] opacity-70 font-medium uppercase tracking-wider">Music by TocaAI</span>
        <div className="flex items-center gap-1 overflow-hidden max-w-[100px]">
          {isPlaying && (
            <motion.div 
              animate={{ height: [4, 8, 4] }} 
              transition={{ repeat: Infinity, duration: 0.8 }}
              className={`w-0.5 rounded-full ${isDark ? 'bg-white' : 'bg-black'}`}
            />
          )}
          <span className="text-xs font-bold truncate">{trackName}</span>
        </div>
      </div>
    </motion.button>
  );
};

