          <Link to="/" className="text-blue-400 underline">Return Home</Link>
        </div>
      </div>
    );
  }

  // --- Theme Logic ---
  const getThemeClasses = () => {
    switch (event.type) {
      case ThemeType.WEDDING:
        return {
          wrapper: 'bg-wedding-cream font-wedding text-slate-800',
          accent: 'text-wedding-gold',
          buttonPrimary: 'bg-wedding-gold text-white shadow-wedding-gold/30',
          nav: 'bg-white/80 border-t border-wedding-gold/20 text-slate-600',
          navActive: 'text-wedding-gold',
          modal: 'bg-[#FFFDF5] text-slate-800',
          isDark: false
        };
      case ThemeType.BIRTHDAY:
        return {
          wrapper: 'bg-bday-dark font-bday text-white',
          accent: 'text-bday-neon drop-shadow-[0_0_10px_rgba(123,44,191,0.5)]',
          buttonPrimary: 'bg-gradient-to-r from-purple-600 to-blue-600 shadow-purple-500/30',
          nav: 'bg-black/80 border-t border-white/10 text-gray-400',
          navActive: 'text-white drop-shadow-[0_0_8px_rgba(255,255,255,0.8)]',
          modal: 'bg-[#1A1A24] text-white border-t border-white/10',
          isDark: true
        };
      case ThemeType.CORPORATE:
        return {
          wrapper: 'bg-corp-gray font-corp text-slate-900',
          accent: 'text-corp-blue',
          buttonPrimary: 'bg-corp-blue text-white shadow-blue-500/20',
          nav: 'bg-white border-t border-gray-200 text-slate-400',
          navActive: 'text-corp-blue',
          modal: 'bg-white text-slate-900',
          isDark: false
        };
    }
  };

  const theme = getThemeClasses();

  return (
    <div className={`min-h-screen relative overflow-x-hidden ${theme.wrapper}`}>

      {/* TocaAI Music Widget */}
      <TocaPlayer trackName={event.musicTrack} isDark={theme.isDark} />

      {/* Hero Section */}
      <div className="relative h-screen w-full">
