            src={event.heroImage} 
            alt="Event Hero" 
            className="w-full h-full object-cover"
          />
          <div className={`absolute inset-0 ${theme.isDark ? 'bg-gradient-to-t from-black via-black/40 to-transparent' : 'bg-gradient-to-t from-white via-white/40 to-transparent'}`} />
        </div>

        {/* Hero Content */}
        <div className="absolute bottom-24 left-0 w-full px-6 z-10 pb-8">
          <motion.div
            initial={{ y: 20, opacity: 0 }}
            animate={{ y: 0, opacity: 1 }}
            transition={{ duration: 0.8 }}
          >
            <p className="uppercase tracking-[0.2em] text-xs font-semibold mb-2 opacity-80">{event.hosts}</p>
            <h1 className={`text-5xl mb-4 leading-tight ${event.type === ThemeType.WEDDING ? 'font-italic' : 'font-bold'}`}>
              {event.title}
            </h1>

            <div className="flex items-center gap-4 mb-8 text-sm font-medium opacity-90">
              <div className="flex items-center gap-1.5 px-3 py-1.5 rounded-full backdrop-blur-md bg-white/10 border border-white/20">
                <Calendar size={14} />
                <span>{event.date}</span>
              </div>
              <div className="flex items-center gap-1.5 px-3 py-1.5 rounded-full backdrop-blur-md bg-white/10 border border-white/20">
                <MapPin size={14} />
