              </div>
            </div>

            <Button 
              className={`${theme.buttonPrimary} w-full py-4 text-lg`}
              onClick={() => setRSVPOpen(true)}
            >
              RSVP Now
            </Button>
          </motion.div>
        </div>
      </div>

      {/* Details Section (Below fold) */}
      <div className={`px-6 py-12 ${theme.wrapper} min-h-[50vh]`}>
