             <div className="flex items-start gap-4 mb-4">
                <MapPin className={theme.accent} size={24} />
                <div>
                  <h4 className="font-bold text-lg">{event.locationName}</h4>
                  <p className="opacity-70">{event.address}</p>
                  <a href="#" className={`text-sm underline mt-1 block ${theme.accent}`}>Open in Maps</a>
                </div>
             </div>
             <div className="flex items-start gap-4">
                <Calendar className={theme.accent} size={24} />
                <div>
                  <h4 className="font-bold text-lg">{event.date}</h4>
                  <p className="opacity-70">{event.time}</p>
