        isOpen={isRSVPOpen} 
        onClose={() => { setRSVPOpen(false); setTimeout(() => setRsvpStep('form'), 300); }} 
        title={rsvpStep === 'form' ? "Will you attend?" : "You're on the list!"}
        themeClasses={theme.modal}
      >
        {rsvpStep === 'form' ? (
           <form className="space-y-4" onSubmit={(e) => { e.preventDefault(); setRsvpStep('success'); }}>
