                 <option value="1" className="text-black">Just me</option>
                 <option value="2" className="text-black">+1 Guest</option>
               </select>
             </div>

             <div className="pt-4">
                <Button type="submit" fullWidth className={theme.buttonPrimary}>Confirm Attendance</Button>
             </div>
           </form>
        ) : (
          <div className="text-center py-8">
            <motion.div 
              initial={{ scale: 0.5, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              className={`w-20 h-20 rounded-full mx-auto flex items-center justify-center mb-4 ${theme.isDark ? 'bg-green-500/20 text-green-400' : 'bg-green-100 text-green-600'}`}
